import {SEGMENTS, parseSegment, applyThrow, getCheckout, trainingStats as stats} from './engine.js';
import {mountCoach} from './coach.js';

const paths = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="4"/>',
 route:'<circle cx="6" cy="6" r="2"/><circle cx="18" cy="18" r="2"/><path d="M8 6h7a3 3 0 0 1 0 6H9a3 3 0 0 0 0 6h7"/>',
 history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2"/>',
 settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',
 bulb:'<path d="M9 18h6m-6 3h6M8 15a6 6 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',
 arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',
 chart:'<path d="M4 20V4m0 16h17M8 14l4-5 4 3 5-7"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
 flame:'<path d="M12 3c2 5-2 6 0 9 1-1 3-2 3-5 7 6 5 14-3 14-7 0-9-7-5-12 0 4 2 4 2 4-1-5 3-6 3-10z"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 close:'<path d="m6 6 12 12M18 6 6 18"/>',
 undo:'<path d="M3 10h10a6 6 0 0 1 0 12M3 10l6-6m-6 6 6 6"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 0-1 1-1 3m0 2h.01"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>'
};
const icon = (name, cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.target}</svg>`;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHtml = value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const KEY='dartboard.training.v1';
let data;
try{data=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
if(!data||!Array.isArray(data.sessions))data={sessions:[],profile:{name:'',hand:'right'},active:null};
data.profile ||= {name:'',hand:'right'};
let view='overview', multiplier='S', cleanupCoach=null, chartRange=7, checkoutScore=121, checkoutDarts=3;
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(data));}catch{toast('Storage is unavailable. Export your sessions before closing.');}};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
const fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:1,minimumFractionDigits:1});
const duration=s=>{const mins=Math.round((s.duration||0)/60);return mins>=60?`${Math.floor(mins/60)}h ${mins%60}m`:`${Math.max(1,mins)} min`;};
const dateText=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const dateFull=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const today=d=>new Date(d).toDateString()===new Date().toDateString();
const labels={overview:'Overview',practice:'Practice',coach:'Form coach',checkout:'Checkout lab',sessions:'My sessions'};
const navIcons={overview:'grid',practice:'target',coach:'camera',checkout:'route',sessions:'history'};
$$('[data-nav]').forEach(a=>{const k=a.dataset.nav;a.innerHTML=icon(navIcons[k])+labels[k]+(k==='coach'?'<span class="nav-tag">BETA</span>':'');});
$('#settings-btn').innerHTML=icon('settings')+'Settings';$('#tip-icon').innerHTML=icon('bulb');$('#help-btn').innerHTML=icon('help');
function updateProfile(){const name=data.profile.name;$('#profile-name').textContent=name||'Your practice';$('.profile .avatar').textContent=$('#header-avatar').textContent=(name||'Y').slice(0,1).toUpperCase();}
updateProfile();

function sampleSessions(){return Array.from({length:8},(_,i)=>{const dt=new Date();dt.setDate(dt.getDate()-(7-i));dt.setHours(17,30,0,0);const target=i%3===1?'D16':'T20';const pool=target==='D16'?['S16','D16','S8','D16','S16','MISS','D16','S7','D8']:['S20','T20','S1','S20','S5','T20','S20','T5','MISS'];const throws=Array.from({length:30},(_,j)=>({segment:pool[(j*7+i*2)%pool.length],target,at:dt.toISOString()}));return {id:`sample-${i}`,mode:'accuracy',name:target==='D16'?'Double 16 focus':'Treble 20 practice',target,throws,startedAt:dt.toISOString(),duration:480+i*33,sample:true};}).reverse();}
const isDemo=()=>data.sessions.length===0;
const displayedSessions=()=>isDemo()?sampleSessions():data.sessions;
function overall(sessions){const rows=sessions.map(stats);const throws=rows.reduce((n,s)=>n+s.throws,0),score=rows.reduce((n,s)=>n+s.score,0),averageDarts=rows.reduce((n,s)=>n+s.averageDarts,0),hits=rows.reduce((n,s)=>n+s.hits,0),attempts=rows.reduce((n,s)=>n+s.attempts,0);return {throws,score,hits,hitRate:attempts?hits/attempts*100:0,threeDartAverage:averageDarts?score/averageDarts*3:0,bestVisit:Math.max(0,...rows.map(s=>s.bestVisit))};}

function dartboard(interactive=false,hero=false){
 const nums=[20,1,18,4,13,6,10,15,2,17,3,19,7,16,8,11,14,9,12,5];
 const p=(r,a)=>[210+r*Math.cos(a*Math.PI/180),210+r*Math.sin(a*Math.PI/180)];
 const wedge=(r1,r2,a,b)=>{const a1=p(r1,a),b1=p(r1,b),a2=p(r2,a),b2=p(r2,b);return `M${a1.join(',')} A${r1} ${r1} 0 0 1 ${b1.join(',')} L${b2.join(',')} A${r2} ${r2} 0 0 0 ${a2.join(',')} Z`;};
 const attr=id=>interactive?`data-segment="${id}" role="button" tabindex="0" aria-label="Log ${escapeHtml(parseSegment(id).label)}"`:'';
 let svg=`<svg class="dartboard-svg ${interactive?'interactive-board':''}" viewBox="0 0 420 420" role="group" aria-label="${interactive?'Interactive dartboard. Select the segment your dart hit.':'Illustration of a dartboard'}"><circle cx="210" cy="210" r="202" fill="#c4c6c1"/><circle cx="210" cy="210" r="198" fill="#27313a"/><circle cx="210" cy="210" r="171" fill="#b7bbb3"/>`;
 nums.forEach((n,i)=>{let a=-99+i*18,b=a+18;[[168,156,i%2?'#769886':'#ce775f','D'],[156,106,i%2?'#e7dfce':'#303b41','S'],[106,96,i%2?'#769886':'#ce775f','T'],[96,17,i%2?'#e7dfce':'#303b41','S']].forEach(([r1,r2,color,m])=>{svg+=`<path d="${wedge(r1,r2,a,b)}" fill="${color}" stroke="#b9beb4" stroke-width="1" ${attr(m+n)}><title>${m==='S'?'Single':m==='T'?'Treble':'Double'} ${n}</title></path>`;});const np=p(183,a+9);svg+=`<text x="${np[0]}" y="${np[1]+4}" text-anchor="middle" fill="#d7dbd5" font-size="16" font-family="Arial,sans-serif" font-weight="400" aria-hidden="true">${n}</text>`;});
 svg+=`<circle cx="210" cy="210" r="17" fill="#6e9683" stroke="#b9beb4" ${attr('SB')}/><circle cx="210" cy="210" r="7" fill="#cf755d" stroke="#b9beb4" ${attr('DB')}/>`;
 if(hero){[[210,109,1],[202,113,.94],[218,119,.9]].forEach(([x,y,scale])=>{svg+=`<g transform="translate(${x} ${y}) rotate(-35) scale(${scale})"><path d="M0 0 37-43" stroke="#adb8b7" stroke-width="2"/><path d="M35-41 70-82" stroke="#a4aaa4" stroke-width="5"/><path d="M39-45 66-77" stroke="#e3e6dd" stroke-width="2" stroke-dasharray="2 2"/><path d="m68-80 21-25 1 20-20 17z" fill="#e4ddd0"/><path d="m69-79 3-27 17 1z" fill="#faf5ec"/><path d="m68-80 4-26-10 12z" fill="#cf7c60"/></g>`;});}
 return svg+'</svg>';
}
function heading(title,desc,action=''){return `<div class="page-heading"><div><p class="eyebrow">A LITTLE BETTER, EVERY THROW</p><h1>${title}</h1><p>${desc}</p></div>${action||`<span class="date-label">${icon('calendar')}${new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'long'})}</span>`}</div>`;}
function sessionRows(rows){return rows.map(s=>{const st=stats(s);return `<tr data-session="${s.id}" tabindex="0" role="button" aria-label="View ${escapeHtml(s.name)}"><td><span class="session-name">${icon(s.mode==='x01'?'route':'target')}${escapeHtml(s.name)}</span></td><td>${dateText(s.startedAt)}</td><td><span class="type-badge ${s.mode==='x01'?'peach':''}">${s.mode==='x01'?'Double-out':'Accuracy'}</span></td><td>${st.throws} darts</td><td>${duration(s)}</td><td>${fmt(st.threeDartAverage)}</td><td class="table-arrow">›</td></tr>`;}).join('');}
function table(rows){return `<table class="session-table"><thead><tr><th>Session</th><th>Date</th><th>Training type</th><th>Darts thrown</th><th>Duration</th><th>3-dart avg.</th><th></th></tr></thead><tbody>${sessionRows(rows)}</tbody></table>`;}
function bindRows(){ $$('[data-session]').forEach(row=>{const open=()=>showSession(row.dataset.session);row.addEventListener('click',open);row.addEventListener('keydown',e=>{if(e.key==='Enter')open();});});}

function renderOverview(){const sessions=displayedSessions(),o=overall(sessions),demo=isDemo(),realToday=data.sessions.filter(s=>today(s.startedAt)).reduce((n,s)=>n+s.throws.length,0),goal=60,progress=demo?42:realToday,minutes=Math.round(sessions.reduce((n,s)=>n+s.duration,0)/60);
 $('#main').innerHTML=`<section>${heading(`Let’s make every dart count${data.profile.name?', '+escapeHtml(data.profile.name):''}.`,'Your progress, your practice, your next personal best.')}
 <div class="hero-grid"><div class="hero"><div class="hero-copy"><p class="eyebrow">PRACTICE WITH PURPOSE</p><h2>Build a more<br><span>consistent throw.</span></h2><p>Find your rhythm. Refine your aim.<br>Turn small improvements into big finishes.</p><button class="primary-button" id="hero-start">Start a practice ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true">${dartboard(false,true)}<span class="hero-spark">✧</span><div class="hero-score"><span class="score-icon">✓</span><span><strong>One dart at a time.</strong><small>That’s how progress happens.</small></span></div></div></div>
 <div class="daily-card"><div class="daily-top"><span>YOUR DAILY GOAL</span>${icon('flame')}</div><h3>Small sessions.<br>Serious progress.</h3><div class="daily-progress"><strong>${progress}</strong><span>/ ${goal} darts</span></div><div class="progress-track"><span style="width:${Math.min(100,progress/goal*100)}%"></span></div><div class="daily-bottom"><span>${Math.min(100,Math.round(progress/goal*100))}% complete</span><span>${demo?'Sample goal':progress>=goal?'Goal reached!':'You’ve got this.'}</span></div><span class="leaf-mark" aria-hidden="true">❧</span></div></div>
 <div class="section-heading"><h2>Your game at a glance</h2><span class="sample-pill"><i></i>${demo?'SAMPLE TRAINING DATA':'YOUR SAVED SESSIONS'}</span></div>
 <div class="stats-grid">${statCard('3-dart average',fmt(o.threeDartAverage),'chart','Points per three darts','avg')}${statCard('Target hit rate',fmt(o.hitRate)+'<small>%</small>','target','Exact target hits / attempts','hit')}${statCard('Practice sessions',sessions.length,'history',`${o.throws} darts logged`,'sessions')}${statCard('Time at the oche',Math.floor(minutes/60)+'<small>h</small> '+minutes%60+'<small>m</small>','clock','Time spent building your game','time')}</div>
 <div class="dashboard-lower"><div class="panel"><div class="panel-head"><div><h2 class="panel-title">A little better, session by session</h2><p class="panel-subtitle">Your scoring average and target accuracy</p></div><select class="small-select" id="chart-range" aria-label="Progress chart range"><option value="7" ${chartRange===7?'selected':''}>Last 7 sessions</option><option value="30" ${chartRange===30?'selected':''}>Last 30 sessions</option></select></div><div class="chart-legend"><span><i></i>3-dart average</span><span><i></i>Hit rate (%)</span></div><div class="chart-container" id="progress-chart">${chart(sessions)}</div></div>
 <div class="panel"><div class="panel-head"><div><h2 class="panel-title">Find your next focus</h2><p class="panel-subtitle">A smarter way to spend your practice</p></div></div><div class="practice-list"><button class="practice-row" data-focus="accuracy"><span class="tool-icon">${icon('target')}</span><span><strong>Make accuracy a habit</strong><small>30 darts. One target. Total focus.</small></span><span class="row-arrow">↗</span></button><button class="practice-row" data-focus="coach"><span class="tool-icon green">${icon('camera')}</span><span><strong>See your throw differently</strong><small>Slow-motion video & pose comparison</small></span><span class="row-arrow">↗</span></button><button class="practice-row" data-focus="checkout"><span class="tool-icon blue">${icon('route')}</span><span><strong>Know your way to zero</strong><small>Plan the finish before you throw.</small></span><span class="row-arrow">↗</span></button></div></div></div>
 <div class="panel recent-panel"><div class="panel-head"><div><h2 class="panel-title">Back at the board</h2><p class="panel-subtitle">${demo?'A preview of your training history':'Your latest training sessions'}</p></div><a class="view-link" href="#sessions">View all sessions <span>→</span></a></div>${table(sessions.slice(0,3))}</div>
 <div class="demo-strip"><span></span>${demo?'You’re viewing sample data. Complete your first practice to start your own story.':'Your training history is stored in this browser. Export a backup from My sessions.'}</div></section>`;
 $('#hero-start').onclick=()=>go('practice');$('#chart-range').onchange=e=>{chartRange=Number(e.target.value);$('#progress-chart').innerHTML=chart(sessions);};$$('[data-focus]').forEach(b=>b.onclick=()=>{if(b.dataset.focus==='accuracy'){go('practice');}else go(b.dataset.focus);});bindRows();
}
function statCard(label,value,type,foot,kind){return `<div class="stat-card"><div class="stat-top"><span>${label}</span>${icon(type)}</div><div class="stat-value">${value}</div><div class="stat-foot">${isDemo()?'<span class="trend-up">Sample</span>':''}<span>${foot}</span><svg class="mini-line" width="48" height="18" viewBox="0 0 48 18" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M1 15 7 13 12 15 18 8 23 11 29 6 34 8 41 3 47 2"/></svg></div></div>`;}
function chart(sessions){const list=[...sessions].reverse().slice(-chartRange), vals=list.map(s=>({avg:stats(s).threeDartAverage,hit:stats(s).hitRate||0,label:dateText(s.startedAt)}));if(!vals.length)return '<div class="empty-state">Your progress chart starts with your first practice.</div>';const width=580,height=180,left=28,right=12,top=17,bottom=32,max=Math.max(100,Math.ceil(Math.max(...vals.map(x=>x.avg))/20)*20),scaleY=v=>height-bottom-v/max*(height-top-bottom),scaleX=i=>left+(vals.length===1?(width-left-right)/2:i/(vals.length-1)*(width-left-right));let grid=[0,.25,.5,.75,1].map(v=>{const y=scaleY(v*max);return `<line x1="${left}" x2="${width-right}" y1="${y}" y2="${y}" stroke="#f0f2f5" stroke-dasharray="3 4"/><text x="${left-9}" y="${y+3}" text-anchor="end" font-size="8" fill="#b2bac4">${Math.round(v*max)}</text>`;}).join('');const path=key=>vals.map((v,i)=>`${i?'L':'M'}${scaleX(i)} ${scaleY(v[key])}`).join(' ');let curves=`<path d="${path('avg')} L${scaleX(vals.length-1)} ${scaleY(0)} L${scaleX(0)} ${scaleY(0)} Z" fill="#fdf2ec" opacity=".65"/><path d="${path('hit')}" fill="none" stroke="#b0c5b5" stroke-width="1.8" stroke-dasharray="4 4"/><path d="${path('avg')}" fill="none" stroke="#ed9174" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>`;return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Progress across ${vals.length} sessions: orange is three-dart average, green is target hit percentage.">${grid}${curves}${vals.map((v,i)=>`<circle cx="${scaleX(i)}" cy="${scaleY(v.avg)}" r="3.2" fill="#ee9a7c" stroke="white" stroke-width="1.8"><title>${v.label}: average ${fmt(v.avg)}, hit rate ${fmt(v.hit)}%</title></circle>${vals.length<10||i%Math.ceil(vals.length/8)===0?`<text x="${scaleX(i)}" y="${height-11}" text-anchor="middle" font-size="8" fill="#a9b2bd">${v.label}</text>`:''}`).join('')}</svg>`;}

function renderPractice(){const active=data.active;
 $('#main').innerHTML=`<section>${heading('Good practice starts here.','Choose a target, log your darts, and make progress you can see.',`<div class="toolbar"><button class="secondary-button" id="practice-help">${icon('help')}How to log</button></div>`)}
 ${active?'':'<div class="notice">Set up your session below. Tap the board or use the number pad to record where each dart lands.</div>'}
 <div class="practice-layout"><div class="panel"><div class="panel-head"><div><h2 class="panel-title">${active?'Your board':'Meet your next target'}</h2><p class="panel-subtitle">${active?'Select the segment you actually hit':'The smallest improvements add up.'}</p></div><span class="type-badge">${active?(active.mode==='x01'?'Double-out':'Accuracy'):'Manual scoring'}</span></div><div class="board-wrap">${dartboard(!!active)}</div><p class="board-hint">${active?'Tap a scoring segment to log a dart.':'Your session begins when you’re ready.'}</p></div>
 <div class="panel" id="practice-controls">${active?liveControls(active):setupControls()}</div></div></section>`;
 $('#practice-help').onclick=()=>openModal('A simple training rhythm',`<p>Throw a dart at the target, then log the segment it actually hit. The app records one dart per tap.</p><ul><li>Use the board, or select Single / Double / Treble and a number.</li><li>Bull is 50. Outer bull is 25. A miss scores 0.</li><li>Accuracy counts an exact segment match to your target.</li><li>Double-out requires exactly zero with the final dart on a double. A bust resets the whole visit.</li></ul>`);
 if(active)bindLive();else bindSetup();
}
function setupControls(){return `<p class="eyebrow">YOUR NEXT SESSION</p><h2 class="panel-title" style="font-size:20px;margin-bottom:7px">A little focus goes a long way.</h2><p class="panel-subtitle" style="margin-bottom:23px">Build a session around the skill you want to improve.</p><div class="form-row"><div class="form-field"><label class="control-label" for="practice-mode">Training mode</label><select class="input" id="practice-mode"><option value="accuracy">Target accuracy</option><option value="x01">501 · Double-out</option></select></div></div><div class="form-row" id="accuracy-fields"><div class="form-field"><label class="control-label" for="practice-target">Your target</label><select class="input" id="practice-target">${targetOptions('T20')}</select></div><div class="form-field"><label class="control-label" for="practice-length">Darts per session</label><select class="input" id="practice-length"><option value="30">30 darts</option><option value="60">60 darts</option><option value="90">90 darts</option></select></div></div><div class="form-row" id="x01-fields" hidden><div class="form-field"><label class="control-label" for="practice-initial">Starting score</label><select class="input" id="practice-initial"><option value="501">501</option><option value="301">301</option><option value="101">101</option></select></div></div><div class="strategy-note"><h3>One thing to focus on</h3><p>Keep your routine repeatable. Aim at the same small point, settle, then throw.</p></div><div class="start-training"><p>A fresh session.<br>A new chance to improve.</p><button class="primary-button" id="begin-session" style="margin-left:auto">Let’s throw ${icon('arrow')}</button></div>`;}
function targetOptions(selected){return [...SEGMENTS.filter(s=>s.multiplier===3),...SEGMENTS.filter(s=>s.isDouble&&s.id!=='DB'),...SEGMENTS.filter(s=>s.multiplier===1&&s.number<=20),parseSegment('SB'),parseSegment('DB')].map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${s.id.startsWith('T')?'Treble '+s.number:s.id.startsWith('D')&&s.id!=='DB'?'Double '+s.number:s.id==='DB'?'Bull · 50':s.id==='SB'?'Outer bull · 25':'Single '+s.number}</option>`).join('');}
function bindSetup(){ $('#practice-mode').onchange=e=>{$('#accuracy-fields').hidden=e.target.value!=='accuracy';$('#x01-fields').hidden=e.target.value!=='x01';};$('#begin-session').onclick=()=>{const mode=$('#practice-mode').value;startSession(mode,mode==='accuracy'?$('#practice-target').value:null,mode==='accuracy'?Number($('#practice-length').value):Number($('#practice-initial').value));};}
function startSession(mode='accuracy',target='T20',value=30){if(data.active){go('practice');toast('Your current session is ready to continue.');return;}const now=new Date().toISOString();data.active={id:crypto.randomUUID(),mode,name:mode==='accuracy'?`${parseSegment(target).label} accuracy`:`${value} double-out`,target,goal:mode==='accuracy'?value:0,initial:mode==='x01'?value:0,remaining:mode==='x01'?value:0,turnStart:mode==='x01'?value:0,dartInVisit:0,throws:[],startedAt:now};persist();go('practice');renderPractice();}
function targetFor(s){if(s.mode==='accuracy')return s.target;const c=getCheckout(s.remaining,3-s.dartInVisit);return c.route[0]||c.setup?.target||'T20';}
function liveControls(s){const st=stats(s),isX=s.mode==='x01',target=targetFor(s),progress=isX?Math.round(((s.initial-s.remaining)/s.initial)*100):Math.round(s.throws.length/s.goal*100);return `<div class="session-summary"><div><p class="remaining-label">${isX?'POINTS REMAINING':'DARTS LOGGED'}</p><strong class="big-remaining">${isX?s.remaining:`${s.throws.length}<small style="font-size:16px;color:#aab2bc;letter-spacing:0"> / ${s.goal}</small>`}</strong></div><div class="session-target"><small>${isX?'SUGGESTED AIM':'YOUR TARGET'}</small><strong>${parseSegment(target).label}</strong></div></div><div class="progress-track" style="background:#f0f2f4;margin-bottom:20px"><span style="width:${progress}%;background:#eaa285"></span></div><div class="panel-head" style="margin-bottom:12px"><label class="control-label" style="margin:0">Where did your dart land?</label><span class="panel-subtitle">${isX?`Visit · dart ${s.dartInVisit+1} of 3`:'One tap = one dart'}</span></div><div class="multipliers">${['S','D','T'].map((m,i)=>`<button data-multiplier="${m}" class="${multiplier===m?'active':''}" aria-pressed="${multiplier===m}">${['Single','Double','Treble'][i]}</button>`).join('')}</div><div class="number-grid">${Array.from({length:20},(_,i)=>`<button data-number="${i+1}" aria-label="Log ${multiplier}${i+1}">${i+1}</button>`).join('')}</div><div class="special-scores"><button data-hit="SB">25 · Outer bull</button><button data-hit="DB">50 · Bull</button><button data-hit="MISS">Miss · 0</button></div><div class="throw-log">${s.throws.length?s.throws.slice(-9).map(t=>`<span class="throw-chip ${t.segment===t.target?'hit':''}" title="${t.bust?'Bust. Whole visit reset.':'Target: '+parseSegment(t.target).label}">${parseSegment(t.segment).label}${t.bust?' ×':''}</span>`).join(''):'<span class="panel-subtitle" style="margin-top:7px">Your first dart starts the story.</span>'}</div><div class="live-stats"><div><strong>${fmt(st.threeDartAverage)}</strong><small>3-dart average</small></div><div><strong>${fmt(st.hitRate||0)}%</strong><small>Target hit rate</small></div><div><strong>${st.bestVisit}</strong><small>Best visit</small></div></div>${isX?`<p class="panel-subtitle">${escapeHtml(getCheckout(s.remaining,3-s.dartInVisit).message)}</p>`:''}<div class="practice-actions"><button class="secondary-button" id="undo-throw" ${!s.throws.length?'disabled':''}>${icon('undo')}Undo</button><button class="primary-button" id="finish-session">Finish & save ${icon('check')}</button></div><button class="text-button" id="discard-session" style="color:#adb2b9;font-size:9px;margin-top:18px">Discard this session</button>`;}
function bindLive(){ $$('[data-multiplier]').forEach(b=>b.onclick=()=>{multiplier=b.dataset.multiplier;$('#practice-controls').innerHTML=liveControls(data.active);bindLiveControls();});bindLiveControls();$$('[data-segment]').forEach(el=>{el.onclick=()=>logThrow(el.dataset.segment);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();logThrow(el.dataset.segment);}};});}
function bindLiveControls(){ $$('[data-multiplier]').forEach(b=>b.onclick=()=>{multiplier=b.dataset.multiplier;$('#practice-controls').innerHTML=liveControls(data.active);bindLiveControls();});$$('[data-number]').forEach(b=>b.onclick=()=>logThrow(multiplier+b.dataset.number));$$('[data-hit]').forEach(b=>b.onclick=()=>logThrow(b.dataset.hit));$('#undo-throw').onclick=undoThrow;$('#finish-session').onclick=()=>finishSession();$('#discard-session').onclick=()=>openModal('Discard this practice?',`<p>This removes the ${data.active.throws.length} darts in your current session.</p>`,`<button class="secondary-button" data-close>Keep practicing</button><button class="primary-button" id="confirm-discard">Discard session</button>`,()=>{$('#confirm-discard').onclick=()=>{data.active=null;persist();closeModal();renderPractice();toast('Session discarded. Ready for a fresh start.');};});}
function logThrow(segment){const s=data.active;if(!s)return;const row={segment,target:targetFor(s),at:new Date().toISOString()};let message='';if(s.mode==='x01'){const result=applyThrow(s.remaining,segment,s.turnStart);s.remaining=result.remaining;s.dartInVisit++;row.bust=result.bust;row.visitEnd=result.bust||result.checkout||s.dartInVisit===3;if(row.visitEnd){s.dartInVisit=0;s.turnStart=s.remaining;}if(result.bust)message=`Bust — ${result.reason.toLowerCase()}. Visit resets to ${s.remaining}.`;if(result.checkout){s.throws.push(row);persist();finishSession(true);return;}}
 s.throws.push(row);persist();$('#practice-controls').innerHTML=liveControls(s);bindLiveControls();if(message)toast(message);if(s.mode==='accuracy'&&s.throws.length>=s.goal)finishSession(true);
}
function undoThrow(){const s=data.active;if(!s?.throws.length)return;const old=s.throws.slice(0,-1);s.throws=[];s.remaining=s.initial;s.turnStart=s.initial;s.dartInVisit=0;for(const original of old){const row={...original};if(s.mode==='x01'){const result=applyThrow(s.remaining,row.segment,s.turnStart);s.remaining=result.remaining;s.dartInVisit++;row.bust=result.bust;row.visitEnd=result.bust||result.checkout||s.dartInVisit===3;if(row.visitEnd){s.dartInVisit=0;s.turnStart=s.remaining;}}s.throws.push(row);}persist();$('#practice-controls').innerHTML=liveControls(s);bindLiveControls();toast('Last dart removed.');}
function finishSession(complete=false){const s=data.active;if(!s?.throws.length){toast('Log a dart before saving your session.');return;}s.duration=Math.max(1,Math.round((Date.now()-new Date(s.startedAt))/1000));s.complete=complete;s.endedAt=new Date().toISOString();data.sessions.unshift(s);data.active=null;persist();const st=stats(s);renderPractice();openModal(complete?(s.mode==='x01'?'That’s a checkout!':'Practice, made progress.'):'Another session in the books.',`<p>${s.mode==='x01'&&complete?'Exactly zero. Finished on a double. Nicely done.':'Your darts are saved. Keep building that consistency.'}</p><div class="result-stats"><div><strong>${st.throws}</strong><small>Darts thrown</small></div><div><strong>${fmt(st.threeDartAverage)}</strong><small>3-dart avg.</small></div><div><strong>${fmt(st.hitRate||0)}%</strong><small>Target hits</small></div></div>`,`<button class="secondary-button" id="result-sessions">View session history</button><button class="primary-button" data-close>Keep practicing</button>`,()=>{$('#result-sessions').onclick=()=>{closeModal();go('sessions');};});}

function renderCheckout(){const result=getCheckout(checkoutScore,checkoutDarts),route=result.finishable?result.route:result.setup?.route||[];
 $('#main').innerHTML=`<section>${heading('See the finish before you throw.','Learn your routes, leave a good double, and find your way to exactly zero.')}<div class="checkout-layout"><div class="panel"><p class="eyebrow">PLAN YOUR CHECKOUT</p><label class="control-label" for="checkout-score">Points remaining</label><input type="number" id="checkout-score" class="score-input" min="2" max="1001" step="1" value="${checkoutScore}" aria-label="Points remaining"><div class="form-row"><div class="form-field"><label class="control-label" for="checkout-darts">Darts in hand</label><select class="input" id="checkout-darts">${[3,2,1].map(x=>`<option value="${x}" ${x===checkoutDarts?'selected':''}>${x} dart${x===1?'':'s'}</option>`).join('')}</select></div></div><div class="quick-scores">${[32,40,81,100,121,170].map(x=>`<button data-score="${x}">${x}</button>`).join('')}</div><button class="primary-button" id="find-route" style="width:100%;margin-top:21px">Find my route ${icon('arrow')}</button><p class="panel-subtitle" style="font-size:9px;line-height:1.8;margin-top:14px">Standard double-out. Inner bull counts as a double. Suggested routes are options, not a unique best choice.</p></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">${result.finishable?'Your route to zero':'Set up your next visit'}</h2><p class="panel-subtitle">${result.finishable?'Stay composed. Take it one dart at a time.':'A smart leave is part of the game.'}</p></div><span class="type-badge ${result.finishable?'':'peach'}">${result.finishable?'Finish available':'Setup visit'}</span></div><div class="checkout-route">${route.map((id,i)=>{const s=parseSegment(id);return `${i?'<span class="route-arrow">→</span>':''}<div class="route-dart ${i===route.length-1&&result.finishable?'finish':''}"><small>DART ${i+1}</small><strong>${s.label}</strong><p>${s.score} points${s.isDouble?' · double':''}</p></div>`;}).join('')}</div><p class="route-message">${escapeHtml(result.message)}</p>${result.finishable?result.alternatives.slice(0,2).map((r,i)=>`<div class="alternative"><span>Alternative ${i+1}</span><strong>${r.map(x=>parseSegment(x).label).join(' → ')}</strong></div>`).join(''):result.setup?`<div class="alternative"><span>Leave for your next visit</span><strong>${result.setup.remaining} points</strong></div>`:''}<div class="strategy-note"><h3>Think one dart ahead.</h3><p>${checkoutScore===170?'170 is the highest three-dart double-out finish: two treble 20s and the bull.':result.finishable?'Recalculate after each dart. A missed treble can still leave a simple route to a double.':'You don’t need to force the finish. Score toward a number you can close on your next visit.'}</p></div><button class="secondary-button" id="practice-checkout" style="margin-top:22px">${icon('target')}Practice from ${checkoutScore}</button></div></div><div class="notice" style="margin-top:23px">Double-out rule: finish on exactly 0 with a double. Going below 0, leaving 1, or reaching 0 without a double busts the whole visit.</div></section>`;
 const update=()=>{const score=Number($('#checkout-score').value),darts=Number($('#checkout-darts').value);if(!Number.isInteger(score)||score<2||score>1001){toast('Enter a whole score from 2 to 1001.');$('#checkout-score').focus();return;}checkoutScore=score;checkoutDarts=darts;renderCheckout();};$('#find-route').onclick=update;$('#checkout-score').onkeydown=e=>{if(e.key==='Enter')update();};$('#checkout-darts').onchange=update;$$('[data-score]').forEach(b=>b.onclick=()=>{checkoutScore=Number(b.dataset.score);renderCheckout();});$('#practice-checkout').onclick=()=>startSession('x01',null,checkoutScore);
}
function renderSessions(filter='all'){const sessions=displayedSessions(),rows=sessions.filter(s=>filter==='all'||s.mode===filter),demo=isDemo();$('#main').innerHTML=`<section>${heading('Your effort, all in one place.','Every session is another step toward a more confident game.',`<div class="toolbar"><button class="secondary-button" id="export-sessions">${icon('download')}Export CSV</button><button class="primary-button" id="new-session">${icon('plus')}New practice</button></div>`)}<div class="session-controls"><span class="sample-pill"><i></i>${demo?'SAMPLE SESSIONS · COMPLETE A PRACTICE TO START YOUR OWN':data.sessions.length+' SAVED SESSION'+(data.sessions.length===1?'':'S')}</span><select class="input" id="session-filter" aria-label="Filter sessions"><option value="all">All training</option><option value="accuracy">Target accuracy</option><option value="x01">Double-out</option></select></div><div class="panel recent-panel all-sessions-panel">${rows.length?table(rows):`<div class="empty-state">${icon('history')}<h3>Your next practice belongs here.</h3><p>No sessions in this training mode yet.</p><button class="primary-button" id="empty-start">Start a practice</button></div>`}</div><div class="notice" style="margin-top:20px">${icon('shield').replace('<svg ','<svg style="width:15px;height:15px;display:inline-block;vertical-align:middle;margin-right:6px" ')}${demo?'These examples show how your history will look.':'Your sessions stay in this browser.'} Export a CSV backup to keep your training records.</div></section>`;$('#session-filter').value=filter;$('#session-filter').onchange=e=>renderSessions(e.target.value);$('#new-session').onclick=()=>go('practice');$('#export-sessions').onclick=exportCSV;$('#empty-start')?.addEventListener('click',()=>go('practice'));bindRows();}
function exportCSV(){const sessions=displayedSessions();const header=['Session','Date','Mode','Target','Darts','Hit rate (%)','3-dart average','Best visit','Duration (seconds)','Sample'];const rows=sessions.map(s=>{const st=stats(s);return [s.name,s.startedAt,s.mode,s.target||'Dynamic checkout',st.throws,fmt(st.hitRate||0),fmt(st.threeDartAverage),st.bestVisit,s.duration,s.sample?'Yes':'No'];});const csv=[header,...rows].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`dartboard-${isDemo()?'sample-':''}sessions-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(isDemo()?'Sample session CSV downloaded.':'Your training backup is downloaded.');}
function showSession(id){const s=displayedSessions().find(s=>s.id===id);if(!s)return;const st=stats(s);openModal(escapeHtml(s.name),`<p>${dateFull(s.startedAt)} · ${duration(s)} · ${s.sample?'Sample session':s.mode==='x01'?s.complete?'Checkout completed':'Double-out practice':'Target accuracy'}</p><div class="result-stats"><div><strong>${st.throws}</strong><small>Darts</small></div><div><strong>${fmt(st.threeDartAverage)}</strong><small>3-dart avg.</small></div><div><strong>${fmt(st.hitRate||0)}%</strong><small>Hit rate</small></div></div><h3>Your darts</h3><div class="throw-log">${s.throws.map(t=>`<span class="throw-chip ${t.target===t.segment?'hit':''}">${parseSegment(t.segment).label}${t.bust?' ×':''}</span>`).join('')}</div><p>${st.hits} exact target hits. Best visit: ${st.bestVisit} points.${s.mode==='x01'?` ${s.remaining} points left.`:''}</p>`,`${s.sample?'':'<button class="secondary-button delete-button" id="delete-session">Delete session</button>'}<button class="primary-button" data-close>Done</button>`,()=>{if(!s.sample)$('#delete-session').onclick=()=>openModal('Delete this session?',`<p>This removes ${escapeHtml(s.name)} and its ${s.throws.length} recorded darts from this device.</p>`,`<button class="secondary-button" data-close>Keep session</button><button class="primary-button" id="delete-confirm">Delete session</button>`,()=>{$('#delete-confirm').onclick=()=>{data.sessions=data.sessions.filter(x=>x.id!==s.id);persist();closeModal();render();toast('Session deleted.');};});});}

function openModal(title,body,buttons='<button class="primary-button" data-close>Got it</button>',after){$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-top"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div>${body}<div class="modal-buttons">${buttons}</div></div>`;$$('[data-close]').forEach(b=>b.onclick=closeModal);if(!$('#modal').open)$('#modal').showModal();after?.();}
function closeModal(){$('#modal').close();}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function settings(){openModal('Make this space yours.',`<p>A few small details for your training space.</p><label><span class="control-label">Your name</span><input class="input" id="setting-name" maxlength="30" placeholder="What should we call you?" value="${escapeHtml(data.profile.name)}"></label><label><span class="control-label">Throwing hand</span><select class="input" id="setting-hand"><option value="right">Right-handed</option><option value="left">Left-handed</option></select></label><p style="font-size:10px">Preferences and training history are saved on this device. Videos are processed locally and are not stored after you leave the form coach.</p>`,`<button class="secondary-button" data-close>Cancel</button><button class="primary-button" id="save-settings">Save preferences</button>`,()=>{$('#setting-hand').value=data.profile.hand;$('#save-settings').onclick=()=>{data.profile={name:$('#setting-name').value.trim(),hand:$('#setting-hand').value};persist();updateProfile();closeModal();render();toast('Your preferences are saved.');};});}
$('#settings-btn').onclick=$('#profile-btn').onclick=settings;
$('#quick-drill').onclick=()=>startSession('accuracy','D16',30);
$('#help-btn').onclick=()=>openModal('A better practice, one dart at a time.',`<ul><li><strong>Pick one focus.</strong> Choose a target and repeat a comfortable, steady routine.</li><li><strong>Track the real result.</strong> Log where each dart lands, including misses.</li><li><strong>Look for consistency.</strong> Review several throws from the same camera angle.</li><li><strong>Plan the finish.</strong> Learn a route, then adjust after every dart.</li></ul><p>Use the Form coach to compare your own clips with a professional reference. Pose measurements are experimental observations, not a verdict on your technique.</p>`);
$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');
document.addEventListener('click',e=>{if(window.innerWidth<=760&&!e.target.closest('#sidebar')&&!e.target.closest('#mobile-menu'))$('#sidebar').classList.remove('open');});
function go(next){if(location.hash==='#'+next){render();return;}location.hash=next;}
function render(){cleanupCoach?.();cleanupCoach=null;view=labels[location.hash.slice(1)]?location.hash.slice(1):'overview';$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-crumb').textContent=labels[view];$('#sidebar').classList.remove('open');if(view==='overview')renderOverview();else if(view==='practice')renderPractice();else if(view==='checkout')renderCheckout();else if(view==='sessions')renderSessions();else{$('#main').innerHTML=`<section>${heading('Better form starts with a closer look.','A private video workspace for more intentional practice.')}<div id="coach-mount"></div></section>`;cleanupCoach=mountCoach($('#coach-mount'));const arm=$('[data-arm]');if(arm)arm.value=data.profile.hand;}document.title=`${labels[view]} · DartBoard`;}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
render();
